function ScoreForm({ players, onSelectPlayer }) {
	const playerObj = players.map((player) => player);

	const {
		id,
		playerName,
		points,
		wins,
		draws,
		losses,
		goalsFor,
		goalsAgainst,
		goalDifference,
	} = playerObj;

	function handleSubmit(e) {
		e.preventDefault();
	}
	return (
		<form onSubmit={handleSubmit}>
			<span>P1 Score</span> : <span>P2 Score</span>
			<select
				value={playerName}
				onChange={(e) => onSelectPlayer(e.target.value)}
			>
				<option value={playerObj[0].playerName}>{playerName}</option>
				<option value={playerObj[1].playerName}>{playerName}</option>
				<option value={playerObj[2].playerName}>{playerName}</option>
			</select>
			{/* <select>
				<option value="">P2</option>
			</select> */}
		</form>
	);
}
export default ScoreForm;
